const BASE = { en, de, ar, tr, ur, fa, ps, fr, es, id, ms, bn, ru, zh };
const TEXT = Object.fromEntries(Object.entries(BASE).map(([k, v]) => [k, { ...enX, ...enY, ...enZ, ...v, ...(X[k] ?? {}), ...(Y[k] ?? {}), ...(Z[k] ?? {}) }])) as unknown as { en: GardenText } & Record<string, GardenText>;
export const gardenText = (lang: string): GardenText => pick(TEXT, lang);
export function useGardenText(): GardenText { const { lang } = useLang(); return pick(TEXT, lang); }
export const fillG = (s: string, v: Record<string, string | number>) => s.replace(/\{(\w+)\}/g, (_, k) => String(v[k] ?? ""));

