const SEASON_NAME: Record<string, keyof StickerNames> = { "ramadan-lantern": "lantern", "ramadan-garland": "garland", "iftar-dates": "dates", "suhoor-moon": "suhoor", "eid-fitr": "fitr", "eid-adha": "adha", "laylat-qadr": "laylat", arafah: "arafah", jumuah: "jumuah", "hijri-new-year": "newYear", ashura: "ashura", ghadir: "ghadir" };
type Named = { id: string; series: string; label: string };
/** the name of a collection sticker as the learner reads it ("17 Ramadan" for e:ramadan-17, "Dschuz 3" for j:3) */
export function stickerLabel(it: Named, lang: string): string {
  const t = STICKER_NAMES[lang] ?? STICKER_NAMES.en;
  if (it.series === "juz") return fillG(t.juz, { n: it.id.slice(2) });
  if (it.series !== "seasonal") return it.label;
  const slug = it.id.slice(2), m = /^(ramadan|qadr|dhulhijjah)-(\d+)$/.exec(slug);
  if (m) return fillG(t[m[1] as "ramadan"], { n: m[2] });
  const k = SEASON_NAME[slug];
  return k ? t[k] : it.label;
}
export function useStickerLabel(): (it: Named) => string { const { lang } = useLang(); return (it) => stickerLabel(it, lang); }














